SELECT 
FROM eqp_ledger
WHERE is_deleted = 0

    AND equipment_code = #{equipmentCode}


    AND equipment_name LIKE CONCAT('%', #{equipmentName}, '%')


    AND category = #{category}


    AND status = #{status}


    AND (equipment_code LIKE CONCAT('%', #{keyword}, '%')
         OR equipment_name LIKE CONCAT('%', #{keyword}, '%')
         OR equipment_model LIKE CONCAT('%', #{keyword}, '%'))

ORDER BY id DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(*)
FROM eqp_ledger
WHERE is_deleted = 0

    AND equipment_code = #{equipmentCode}


    AND equipment_name LIKE CONCAT('%', #{equipmentName}, '%')


    AND category = #{category}


    AND status = #{status}


    AND (equipment_code LIKE CONCAT('%', #{keyword}, '%')
         OR equipment_name LIKE CONCAT('%', #{keyword}, '%')
         OR equipment_model LIKE CONCAT('%', #{keyword}, '%'))
